"""
Git Pre-Commit & Pre-Push Security Hook Installer for Personal Agentic Fleet.
Installs local Git hooks that automatically execute the 6-layer Security & Privacy
Scanner before every commit and push, preventing accidental secret or PII leaks.
Uses native Python shebang on Windows to bypass MSYS2 sh.exe fork issues.
"""

from pathlib import Path
import stat
import sys

ROOT_DIR = Path(__file__).resolve().parent.parent.parent
GIT_HOOKS_DIR = ROOT_DIR / ".git" / "hooks"

HOOK_SCRIPT_TEMPLATE = """#!{python_shebang}
# Auto-generated by Personal Agentic Fleet Security Scanner
import sys
from pathlib import Path

repo_root = Path(__file__).resolve().parent.parent.parent
if str(repo_root) not in sys.path:
    sys.path.insert(0, str(repo_root))

print("[Fleet Security Gate] Running 6-layer Security & Privacy Audit ({hook_name})...")
from fleet.tools.security_scanner import run_security_scan

report = run_security_scan(repo_root=repo_root)
print(f"=== Fleet Security Scan [{{report['status']}}] | Score: {{report['score']}}/100 ({{report['passed_checks']}}/{{report['total_checks']}} checks passed) ===")
if report.get("total_findings", 0) > 0:
    for f in report.get("findings", []):
        print(f"  - [{{f['severity']}}] {{f['file']}}:{{f['line']}} -> {{f['detail']}}")
    print("==================================================================")
    print("[BLOCKED] Fleet Security Gate blocked {hook_name} due to security findings.")
    print("==================================================================")
    sys.exit(1)
sys.exit(0)
"""


def install_git_hooks(repo_root: Path = ROOT_DIR) -> dict:
    """Installs pre-commit and pre-push security hooks into .git/hooks/."""
    hooks_dir = repo_root / ".git" / "hooks"
    if not hooks_dir.exists():
        return {"status": "skipped", "reason": ".git/hooks directory not found"}

    python_shebang = sys.executable.replace("\\", "/") if sys.executable else "/usr/bin/env python"
    installed = []
    for hook_name in ("pre-commit", "pre-push"):
        hook_path = hooks_dir / hook_name
        script_content = HOOK_SCRIPT_TEMPLATE.format(
            python_shebang=python_shebang,
            hook_name=hook_name,
        )
        hook_path.write_text(script_content, encoding="utf-8", newline="\n")
        try:
            hook_path.chmod(hook_path.stat().st_mode | stat.S_IEXEC)
        except Exception:
            pass
        installed.append(str(hook_path))

    return {"status": "installed", "hooks": installed}


if __name__ == "__main__":
    res = install_git_hooks()
    print(f"Git Security Hooks: {res['status']} -> {res.get('hooks', [])}")
    sys.exit(0)

